// ── Construir link permanente de Calendly con fecha preseleccionada ──
// NO usamos /scheduling_links API (Plan Free no fuerza slot)
// Usamos: {calendario_link}/{fecha_local}-05:00

const input = $input.first().json;

const slot_elegido    = input.slot_elegido;    // UTC, ej: "2026-04-18T13:00:00Z"
const calendario_link = input.calendario_link; // ej: "https://calendly.com/ing-diegolrc/new-meeting"
const email           = input.email;
const numero          = input.numero;
const direccion       = input.direccion;
const evolution_instance = input.evolution_instance;
const evolution_api_key  = input.evolution_api_key;

// Convertir UTC → Colombia (UTC-5) en formato YYYY-MM-DDTHH:MM:SS
const fecha_local = new Date(slot_elegido)
  .toLocaleString('sv-SE', { timeZone: 'America/Bogota' })
  .replace(' ', 'T'); // sv-SE da formato ISO, reemplazar espacio por T

// Link final: {calendario_link}/{fecha_local}-05:00
const link_cita = `${calendario_link}/${fecha_local}-05:00`;

// Fecha legible en español
const fecha_display = new Date(slot_elegido).toLocaleString('es-CO', {
  timeZone: 'America/Bogota',
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  hour: '2-digit',
  minute: '2-digit'
});

// Mensaje al lead
const texto = `¡Perfecto! 🎉 Aquí está tu link para reservar la cita:\n\n📅 *${fecha_display}*\n📍 ${direccion}\n\n👉 ${link_cita}\n\n_Confirma en el link y recibirás un correo a ${email}. ¡Solo toma 30 segundos!_ ✅`;

return [{
  json: {
    url: `https://evolution.srv1398596.hstgr.cloud/message/sendText/${evolution_instance}`,
    header_name: 'apikey',
    header_value: evolution_api_key,
    body: JSON.stringify({ number: numero, text: texto }),
    link_cita,
    fecha_display
  }
}];

